<?php require 'config/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$s=$pdo->prepare('SELECT * FROM users WHERE nim=? LIMIT 1');$s->execute([trim($_POST['nim']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'nama'=>$u['nama'],'role'=>$u['role'],'nim'=>$u['nim']];header('Location: index.php');exit;}$err='NIM atau password salah.';}headpage('Login');?><div class="panel p-4 mx-auto" style="max-width:450px"><h2>Login</h2><?php if(isset($err)):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>NIM</label><input name="nim" class="form-control mb-3" required><label>Password</label><input type="password" name="password" class="form-control mb-3" required><button class="btn btn-green">Login</button></form><a href="register.php">Daftar</a></div><?php footpage();?>
